"""Materialize the research report and versioned data without shipping prototype code into src/."""
from pathlib import Path
import json,csv,gzip,hashlib,subprocess
ROOT=Path(__file__).resolve().parents[2];A=ROOT/'artifacts/ruka-build-research';D=ROOT/'docs/research/ruka-exclusive-build';DATA=D/'data';DATA.mkdir(exist_ok=True)
def load(name):return json.loads((A/name).read_text())
final=load('prototype-v4-results.json');rows={r['id']:r for r in final['cases']};base=load('baseline.json');variations=load('variation-results.json');adversarial=load('adversarial-results.json');certificate=load('necessity-certificate.json');edges=load('edge-checks.json');assert certificate['passed']and edges['passed']
labels=[('v4-tier3','基本編成・可変石T3上限'),('v4-tier4','基本編成・可変石T4上限'),('v4-tier5','基本編成・可変石T5上限'),('v4-tier6','基本編成・可変石T6上限'),('v4-guard-liora','守り役を覚醒リオラへ'),('v4-guard-neri','守り役をネリへ'),('v4-no-athena-budget','通常セリス・通常リオラ・T3中心'),('v4-without-new-skill','ルカはいるが新技なし'),('v4-ruka-no-generator','ルカ＋攻撃役3人、障壁供給なし'),('v4-without-new-gem','新石を使わず既存の障壁で供給'),('v4-athena-leader','アテナをリーダーへ'),('v4-cast-too-early','留め縫いが早すぎる操作'),('v4-cast-too-late','留め縫いが遅すぎる操作'),('v4-no-sideactions-no-potions','薬・妖精・花を使用しない'),('v4-t6-burst-no-ruka','ルカなし・T6火力編成'),('v4-t6-athena-turtle','ルカなし・T6耐久編成'),('v4-t6-sleep-control','ルカなし・T6睡眠構成')]
table='| 条件 | 勝利/試行 | 平均R（失敗を含む） |\n|---|---:|---:|\n'+''.join(f"| {label} | {rows[id]['wins']}/{rows[id]['n']} | {rows[id]['meanRounds']:.2f} |\n"for id,label in labels)
vtable='| ルカ以外の仲間 | 勝利/試行 | 平均R |\n|---|---:|---:|\n'+''.join(f"| {'／'.join({'nox':'ノクス','athena':'アテナ','benzaiten':'弁財天','elaine':'通常エレイン','liora-awakened':'覚醒リオラ','seris-awakened':'覚醒セリス'}[x]for x in r['party'][1:])} | {r['wins']}/{r['n']} | {r['meanRounds']:.2f} |\n"for r in variations['cases'])
counts={name:sum(r['n']for r in load(name)['cases'])for name in ['prototype-v1-results.json','prototype-v2-results.json','prototype-v3-results.json','prototype-v4-results.json','timing-results.json','variation-results.json']};counts['baseline.json']=len(base['rows'])*20;counts['adversarial-results.json']=adversarial['totalBattles'];total=sum(counts.values())
p=D/'README.md';s=Path(__file__).with_name('report-template.txt').read_text();s=s.replace('@@MAIN_TABLE@@',table).replace('@@VARIATION_TABLE@@',vtable).replace('@@TIER_GAIN@@',f"{(1-rows['v4-tier6']['meanRounds']/rows['v4-tier3']['meanRounds'])*100:.2f}").replace('@@RUN_COUNTS@@',f'延べ **{total:,}戦**。各版の対照条件の再実行と同じseedの比較を含み、独立した{total:,}人のプレイを意味しない。現行比較2,840戦、初案2,000戦、第2案2,900戦、第3案2,100戦、最終案2,100戦、70体置換等1,700戦、必殺温存600戦、仲間置換400戦。')
assert '@@'not in s;p.write_text(s)
for name in [*counts,'example-trace.json','prototype-hashes.json','prototype-v1-hashes.json','prototype-v2-hashes.json','prototype-v3-hashes.json']:
 data=(A/name).read_bytes();(DATA/(name+'.gz')).write_bytes(gzip.compress(data,mtime=0))
for name in ['necessity-certificate.json','edge-checks.json']:(DATA/name).write_bytes((A/name).read_bytes())
with(DATA/'final-summary.csv').open('w',newline='')as f:
 w=csv.writer(f);w.writerow(['condition','label','wins','trials','mean_rounds_including_failures','minimum_rounds','maximum_rounds','mean_blocked_restorations','mean_restorations'])
 for id,label in labels:
  r=rows[id];w.writerow([id,label,r['wins'],r['n'],r['meanRounds'],r['minRounds'],r['maxRounds'],r['meanBlocked'],r['meanResets']])
manifest={'sourceGameCommit':'1f4e970117c95a11ef38c8f1e12fe232e5a7b964','researchParentCommit':'8ad00f6b97245b8829d3ada2ab03fc30dd6aa3e4','liveSrcDiff':subprocess.check_output(['git','diff','--name-only','1f4e970117c95a11ef38c8f1e12fe232e5a7b964','--','src'],cwd=ROOT,text=True).strip(),'totalSimulationsIncludingRepeatedControls':total,'counts':counts,'ruleScope':'Prototype only; no deployed gameplay or human play-test claim. Necessary archetype, not one fixed four-person party.','files':{str(p.relative_to(D)):hashlib.sha256(p.read_bytes()).hexdigest()for p in sorted(DATA.iterdir())if p.is_file()}};assert not manifest['liveSrcDiff'];(D/'Research-Manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2));print('RESEARCH REPORT READY',total,'simulations',len(manifest['files']),'data files')
